<template><a-spin :spinning="loading">
  <template v-if="section==='api-keys'"><div class="toolbar"><a-button type="primary" @click="keyVisible=true"><PlusOutlined/>创建 API Key</a-button></div><a-card class="panel-card"><a-table :data-source="keys" :columns="keyColumns" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.key==='status'"><a-switch :checked="record.is_active" @change="toggleKey(record)"/></template><template v-if="column.key==='time'">{{formatTime(record.created_at)}}</template><template v-if="column.key==='action'"><a-popconfirm title="确定删除？" @confirm="deleteKey(record)"><a-button danger type="link">删除</a-button></a-popconfirm></template></template></a-table></a-card><a-modal v-model:open="keyVisible" title="创建 API Key" @ok="createKey"><a-input v-model:value="keyName" placeholder="密钥名称"/></a-modal></template>
  <template v-else-if="section==='notifications'"><div class="toolbar"><a-button type="primary" @click="channelVisible=true"><PlusOutlined/>添加通知渠道</a-button></div><a-list :data-source="channels" :grid="{gutter:16,xs:1,lg:2}"><template #renderItem="{item}"><a-list-item><a-card class="panel-card" :title="item.channel_name"><template #extra><a-switch :checked="item.is_enabled" @change="toggleChannel(item)"/></template><a-descriptions :column="1" size="small"><a-descriptions-item label="类型">{{item.channel_type}}</a-descriptions-item><a-descriptions-item label="描述">{{item.description||'-'}}</a-descriptions-item></a-descriptions><a-space><a-button size="small" @click="testChannel(item)">测试</a-button><a-popconfirm title="确定删除？" @confirm="deleteChannel(item)"><a-button size="small" danger>删除</a-button></a-popconfirm></a-space></a-card></a-list-item></template></a-list><a-modal v-model:open="channelVisible" title="添加通知渠道" @ok="createChannel"><a-form layout="vertical"><a-form-item label="渠道类型"><a-select v-model:value="channelForm.channel_type" :options="channelTypes"/></a-form-item><a-form-item label="名称"><a-input v-model:value="channelForm.channel_name"/></a-form-item><a-form-item label="凭据 / Token"><a-input-password v-model:value="channelForm.credential"/></a-form-item><a-form-item label="目标 ID / 服务地址"><a-input v-model:value="channelForm.target"/></a-form-item></a-form></a-modal></template>
  <template v-else-if="section==='emby'"><a-row :gutter="16" style="margin-bottom:18px"><a-col :span="12"><a-card class="stat-card"><a-statistic title="媒体项目" :value="embyStatus.total_items||0"/></a-card></a-col><a-col :span="12"><a-card class="stat-card"><a-statistic title="同步状态" :value="embyStatus.is_running?'运行中':'空闲'"/></a-card></a-col></a-row><a-card class="panel-card form-card"><a-form layout="vertical" @finish="saveEmby"><a-form-item label="Emby 地址"><a-input v-model:value="emby.emby_url"/></a-form-item><a-form-item label="API Key"><a-input-password v-model:value="emby.emby_api_key"/></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="同步 Cron"><a-input v-model:value="emby.sync_cron"/></a-form-item></a-col><a-col :span="12"><a-form-item label="媒体库 ID"><a-input v-model:value="emby.selected_libraries"/></a-form-item></a-col></a-row><a-checkbox-group v-model:value="embyFlags" :options="embyOptions"/><div style="margin-top:24px"><a-space><a-button type="primary" html-type="submit">保存设置</a-button><a-button @click="startEmby">立即同步</a-button></a-space></div></a-form></a-card></template>
  <template v-else-if="section==='rate'"><a-row :gutter="16" style="margin-bottom:18px"><a-col v-for="x in rateStats" :key="x.title" :xs="12" :lg="6"><a-card class="stat-card"><a-statistic :title="x.title" :value="x.value"/></a-card></a-col></a-row><a-card class="panel-card form-card"><a-form layout="vertical" @finish="saveRate"><a-row :gutter="16"><a-col :span="8"><a-form-item label="QPS"><a-input-number v-model:value="rate.qps" :min="1"/></a-form-item></a-col><a-col :span="8"><a-form-item label="QPM"><a-input-number v-model:value="rate.qpm" :min="1"/></a-form-item></a-col><a-col :span="8"><a-form-item label="QPH"><a-input-number v-model:value="rate.qph" :min="1"/></a-form-item></a-col></a-row><a-button type="primary" html-type="submit">更新速率限制</a-button></a-form></a-card></template>
  <template v-else-if="section==='network'"><a-card class="panel-card form-card"><a-form layout="vertical" @finish="saveNetwork"><a-form-item label="HTTP 代理"><a-input v-model:value="network.http_proxy"/><a-button style="margin-top:8px" @click="testProxy">测试连接</a-button></a-form-item><a-divider>任务并发</a-divider><a-row :gutter="16"><a-col v-for="f in threadFields" :key="f.key" :xs="24" :md="12"><a-form-item :label="f.label"><a-input-number v-model:value="threads[f.key]" :min="1" style="width:100%"/></a-form-item></a-col></a-row><a-button type="primary" html-type="submit">保存设置</a-button></a-form></a-card></template>
  <template v-else-if="section==='update'"><a-card class="panel-card" title="可用版本"><a-list :data-source="updates"><template #renderItem="{item}"><a-list-item><a-list-item-meta :title="item.version||item.tag_name" :description="item.date||item.publish_date||item.published_at"/><a-tag v-if="item.current" color="success">当前版本</a-tag><a-tag v-else-if="item.latest" color="blue">最新版本</a-tag><a-popconfirm v-if="!item.current" title="确定更新到此版本？" @confirm="updateTo(item)"><a-button type="primary">更新</a-button></a-popconfirm></a-list-item></template></a-list></a-card></template>
  <template v-else-if="section==='maintenance'"><div class="settings-grid"><a-card class="panel-card" title="数据库修复"><p class="muted">重建缺失表，不影响已有数据。</p><a-popconfirm title="确定执行修复？" @confirm="repair"><a-button type="primary">执行修复</a-button></a-popconfirm></a-card><a-card class="panel-card" title="危险区域"><a-alert type="error" show-icon message="清空所有业务表不可恢复"/><a-button danger style="margin-top:20px" @click="deleteVisible=true">清空所有数据</a-button></a-card></div><a-modal v-model:open="deleteVisible" title="确认清空所有数据" @ok="deleteAll"><p>请输入 DELETE 确认：</p><a-input v-model:value="deleteText"/></a-modal></template>
  <template v-else-if="section==='logs'"><div class="toolbar"><a-select v-model:value="logFile" :options="logOptions" style="width:180px" @change="loadLogs"/><a-button :href="`/api/logs/download?path=${logFile}`"><DownloadOutlined/>下载日志</a-button></div><div class="code-log"><div v-for="(line,i) in logs" :key="i">{{line.timestamp}} [{{line.level}}] {{line.message}}</div></div></template>
  <template v-else-if="section==='user'"><a-card class="panel-card form-card"><a-form layout="vertical" @finish="saveUser"><a-form-item label="用户名"><a-input v-model:value="userForm.username"/></a-form-item><a-form-item label="新密码"><a-input-password v-model:value="userForm.new_password"/></a-form-item><a-form-item label="确认密码"><a-input-password v-model:value="userForm.confirm"/></a-form-item><a-button type="primary" html-type="submit">更新账号</a-button></a-form></a-card></template>
  <template v-else><a-card class="panel-card"><a-typography-title :level="3">推荐流程</a-typography-title><a-steps direction="vertical" :items="helpSteps"/><a-alert type="warning" show-icon message="115 开放平台有严格 QPS 限制，建议 QPS 保持为 1。"/><a-button type="link" href="https://github.com/qicfan/qmediasync" target="_blank">GitHub 项目与问题反馈</a-button></a-card></template>
</a-spin></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{message,Modal}from'ant-design-vue';import{PlusOutlined,DownloadOutlined}from'@ant-design/icons-vue';import{del,get,post,put}from'../../services/http';import{formatTime}from'../../core/format';import{useSessionStore}from'../../stores/session';import type{APIKeyItem,AnyMap,NotificationChannel}from'../../types';const props=defineProps<{section:string}>(),session=useSessionStore(),loading=ref(false),keys=ref<APIKeyItem[]>([]),channels=ref<NotificationChannel[]>([]),updates=ref<AnyMap[]>([]),logs=ref<AnyMap[]>([]),keyVisible=ref(false),keyName=ref(''),channelVisible=ref(false),deleteVisible=ref(false),deleteText=ref(''),logFile=ref('app.log'),emby=reactive<AnyMap>({}),embyStatus=reactive<AnyMap>({}),embyFlags=ref<string[]>([]),network=reactive({http_proxy:''}),threads=reactive<AnyMap>({}),rate=reactive({qps:1,qpm:60,qph:3600}),rateData=reactive<AnyMap>({}),userForm=reactive({username:session.user?.username||'',new_password:'',confirm:''}),channelForm=reactive({channel_type:'telegram',channel_name:'',credential:'',target:''});const keyColumns=[{title:'名称',dataIndex:'name'},{title:'前缀',dataIndex:'key_prefix'},{title:'状态',key:'status'},{title:'创建时间',key:'time'},{title:'操作',key:'action'}],channelTypes=['telegram','meow','bark','serverchan','webhook'].map(value=>({value,label:value})),embyOptions=[['sync_enabled','定时同步'],['sync_all_libraries','全部媒体库'],['enable_refresh_library','刷新媒体库'],['enable_media_notification','媒体通知'],['enable_extract_media_info','提取媒体信息'],['enable_auth','Webhook 鉴权'],['enable_playback_overview','播放概览'],['enable_playback_progress','播放进度'],['enable_delete_netdisk','联动删除']].map(([value,label])=>({value,label})),threadFields=[['download_threads','下载线程'],['file_detail_threads','115 文件详情 QPS'],['openlist_qps','OpenList QPS'],['openlist_retry','OpenList 重试次数'],['openlist_retry_delay','重试间隔'],['file_list_page_size','115 列表分页数量']].map(([key,label])=>({key,label})),logOptions=[['app.log','主日志'],['115.log','115'],['openList.log','OpenList'],['tmdb.log','TMDB'],['baidupan.log','百度网盘'],['web.log','Web']].map(([value,label])=>({value,label})),helpSteps=[{title:'添加并授权网盘账号'},{title:'配置 STRM 并创建同步目录'},{title:'配置 TMDB 与刮削目录'},{title:'通过队列和日志观察任务'}];const rateStats=computed(()=>[{title:'QPS 请求',value:rateData.qps_count||0},{title:'总请求',value:rateData.total_requests||0},{title:'限流次数',value:rateData.throttled_count||0},{title:'平均响应(ms)',value:rateData.avg_response_time_ms||0}]);async function load(){loading.value=true;try{if(props.section==='api-keys')keys.value=await get('/api-keys');else if(props.section==='notifications')channels.value=await get('/setting/notification/channels');else if(props.section==='emby'){const[c,s]=await Promise.all([get<AnyMap>('/setting/emby-config'),get<AnyMap>('/emby/sync/status')]);Object.assign(emby,c.config||c);Object.assign(embyStatus,s);embyFlags.value=embyOptions.filter(x=>emby[x.value]===1).map(x=>x.value)}else if(props.section==='rate')Object.assign(rateData,await get('/115/queue/stats?time_window=3600'));else if(props.section==='network'){const[p,t]=await Promise.all([get<AnyMap>('/setting/http-proxy'),get<AnyMap>('/setting/threads')]);network.http_proxy=p.http_proxy||'';Object.assign(threads,t)}else if(props.section==='update')updates.value=await get('/update/last?channel=github');else if(props.section==='logs')await loadLogs()}finally{loading.value=false}}async function createKey(){const d=await post<AnyMap>('/api-keys',{name:keyName.value});keyVisible.value=false;Modal.info({title:'API Key 仅显示一次',content:d.key});load()}const toggleKey=async(k:APIKeyItem)=>{await put(`/api-keys/${k.id}/status`,{is_active:!k.is_active});load()},deleteKey=async(k:APIKeyItem)=>{await del(`/api-keys/${k.id}`);load()};async function createChannel(){const v=channelForm,b={channel_name:v.channel_name},data:{[key:string]:AnyMap}={telegram:{...b,bot_token:v.credential,chat_id:v.target},meow:{...b,nickname:v.credential,endpoint:v.target},bark:{...b,device_key:v.credential,server_url:v.target},serverchan:{...b,sc_key:v.credential,endpoint:v.target},webhook:{...b,endpoint:v.target||v.credential,method:'POST',template:'{{title}}\n{{content}}',format:'text',auth_type:'none'}};await post(`/setting/notification/channels/${v.channel_type}`,data[v.channel_type]);channelVisible.value=false;load()}const toggleChannel=async(c:NotificationChannel)=>{await post('/setting/notification/channels/status',{channel_id:c.id,is_enabled:!c.is_enabled});load()},testChannel=(c:NotificationChannel)=>post('/setting/notification/channels/test',{channel_id:c.id}).then(()=>message.success('测试通知已发送')),deleteChannel=async(c:NotificationChannel)=>{await del(`/setting/notification/channels/${c.id}`);load()};async function saveEmby(){const data={...emby};embyOptions.forEach(x=>data[x.value]=embyFlags.value.includes(x.value)?1:0);await post('/setting/emby-config',data);message.success('Emby 设置已保存')}const startEmby=()=>post('/emby/sync/start',{}).then(()=>message.success('同步已启动'));async function saveRate(){await post('/115/queue/rate-limit',rate);message.success('速率已更新')}async function saveNetwork(){await Promise.all([post('/setting/http-proxy',network),post('/setting/threads',threads)]);message.success('设置已保存')}const testProxy=()=>post('/setting/test-http-proxy',{http_proxy:network.http_proxy,detailed:0}).then(()=>message.success('代理连接正常')),updateTo=(v:AnyMap)=>post('/update/to-version',{version:v.version||v.tag_name,channel:'github'}),repair=()=>post('/database/repair',{}).then(()=>message.success('修复完成'));async function deleteAll(){if(deleteText.value!=='DELETE')return message.error('确认文字不正确');await post('/database/delete-all-table',{});deleteVisible.value=false}async function loadLogs(){const r=await fetch(`/api/logs/old?path=${encodeURIComponent(logFile.value)}&pos=-1&limit=300&direction=forward`,{credentials:'include'});const d=await r.json();logs.value=(d.entries||[]).reverse()}async function saveUser(){if(userForm.new_password!==userForm.confirm)return message.error('两次密码不一致');await post('/user/change',{username:userForm.username,new_password:userForm.new_password});if(session.user)session.user.username=userForm.username;message.success('账号已更新')}watch(()=>props.section,load);onMounted(load)</script>
